INSERT INTO lineitem SELECT * FROM lineitem WHERE l_orderkey=(SELECT min(o_orderkey) FROM orders WHERE o_comment='q5 fixture order' AND o_custkey=(SELECT c_custkey FROM customer JOIN nation ON c_nationkey=n_nationkey WHERE c_comment='q5 fixture customer' AND n_name='INDIA')) AND l_linenumber=1;
INSERT INTO lineitem SELECT * REPLACE ('q5 duplicate line' AS l_comment) FROM lineitem WHERE l_orderkey=(SELECT min(o_orderkey) FROM orders WHERE o_comment='q5 fixture order' AND o_custkey=(SELECT c_custkey FROM customer JOIN nation ON c_nationkey=n_nationkey WHERE c_comment='q5 fixture customer' AND n_name='INDIA')) AND l_linenumber=1;
INSERT INTO orders SELECT * REPLACE ('q5 duplicate order' AS o_comment) FROM orders WHERE o_orderkey=(SELECT min(o_orderkey) FROM orders WHERE o_comment='q5 fixture order' AND o_custkey=(SELECT c_custkey FROM customer JOIN nation ON c_nationkey=n_nationkey WHERE c_comment='q5 fixture customer' AND n_name='INDIA'));
INSERT INTO customer SELECT * REPLACE ('q5 duplicate customer' AS c_comment) FROM customer WHERE c_custkey=(SELECT c_custkey FROM customer JOIN nation ON c_nationkey=n_nationkey WHERE c_comment='q5 fixture customer' AND n_name='INDIA');
INSERT INTO supplier SELECT * REPLACE ('q5 duplicate supplier' AS s_comment) FROM supplier WHERE s_suppkey=(SELECT s_suppkey FROM supplier JOIN nation ON s_nationkey=n_nationkey WHERE s_comment='q5 fixture supplier' AND n_name='INDIA');
INSERT INTO nation SELECT * REPLACE ('q5 duplicate nation' AS n_comment) FROM nation WHERE n_name='INDIA';
INSERT INTO region SELECT * REPLACE ('q5 duplicate region' AS r_comment) FROM region WHERE r_name='ASIA';
